// Build the client's terminal chunk.
//
// The browser half is plain JavaScript loaded as a prebuilt module, so the only
// build step in this package is inlining the vendored xterm UMD files (and its
// stylesheet) into one chunk. The output is a normal source file in `lib/`, kept
// in the package so a checkout works without running this script; rerun it only
// when the vendored xterm, the stylesheet, or `src/terminal-view.frag.js` changes.
//
// Usage: node tools/build-client-chunk.mjs   (from the package directory)
import { readFile, writeFile } from 'node:fs/promises'
import { fileURLToPath } from 'node:url'
import { dirname, join } from 'node:path'

const here = dirname(fileURLToPath(import.meta.url))
const root = join(here, '..')
const PACKAGE_NAME = '@local/dsh-ssh'
const CHUNK = 'client.term.js'

const read = (relative) => readFile(join(root, relative), 'utf8')

const [xterm, fit, css, fragment] = await Promise.all([
  read('vendor/xterm.js'),
  read('vendor/addon-fit.js'),
  read('vendor/xterm.css'),
  read('src/terminal-view.frag.js'),
])

/** Strip the trailing sourceMappingURL comment: the map is not shipped. */
const stripMapComment = (text) => text.replace(/\n?\/\/# sourceMappingURL=\S+\s*$/, '\n')

/**
 * Wrap one UMD bundle so it runs in the chunk's own CommonJS emulation.
 * Both vendored files take their `module.exports = factory()` branch when
 * `exports` and `module` are objects, which is exactly what this provides.
 */
function commonjs(source) {
  return `(function () { var module = { exports: {} }; (function (exports, module) {\n${stripMapComment(source)}})(module.exports, module); return module.exports })()`
}

const layoutCss = `
.dshssh-term{display:flex;flex-direction:column;height:100%;min-height:0;gap:8px;padding:10px 12px 12px;box-sizing:border-box}
.dshssh-termbar{display:flex;align-items:center;gap:8px;flex:none}
.dshssh-termhost{font-size:13px;font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dshssh-termstate{margin-left:auto;color:var(--dsw-alias-label-tertiary,var(--dsw-alias-label-secondary));font-size:11px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dshssh-termstate[data-phase="exited"]{color:var(--dsw-alias-state-warn-primary)}
.dshssh-termstate[data-phase="error"]{color:var(--dsw-alias-state-error-primary)}
.dshssh-termbody{flex:1;min-height:0;overflow:hidden;padding:4px;border:.5px solid var(--dsw-alias-border-l3,var(--dsw-alias-border-l1));border-radius:10px;background:var(--dsw-alias-bg-base)}
`.trim()

const output = `// GENERATED by tools/build-client-chunk.mjs — do not edit by hand.
//
// Terminal chunk for the SSH panel: xterm 6.0.0 and @xterm/addon-fit 0.11.0
// (both MIT; see vendor/LICENSE.xterm and vendor/LICENSE.addon-fit) are inlined
// because the browser module table exposes only React and the harness's own
// packages, so a plugin ships any other dependency itself.
window.__ModuleLoader__.load({
  id: ${JSON.stringify(PACKAGE_NAME)},
  chunk: ${JSON.stringify(CHUNK)},
  factory: (require) => {
    var module = { exports: {} };
    var exports = module.exports;
    const React = require("react");
    const h = React.createElement;
    const PLUGIN_ID = ${JSON.stringify(PACKAGE_NAME)};
    const TERMINAL_CSS = ${JSON.stringify(`${css}\n${layoutCss}`)};
    const XTerm = ${commonjs(xterm)};
    const FitAddon = ${commonjs(fit)};

    /** Install the chunk's stylesheet once; the disposer removes it. */
    function installTerminalStyles() {
      const tagId = PLUGIN_ID + "/terminal.css";
      if (document.querySelector('style[data-plugin-css="' + tagId.replace(/"/g, '\\\\"') + '"]') !== null) return () => {};
      const tag = document.createElement("style");
      tag.dataset.plugin = PLUGIN_ID;
      tag.dataset.pluginCss = tagId;
      tag.textContent = TERMINAL_CSS;
      document.head.appendChild(tag);
      return () => tag.remove();
    }

${fragment}
    return module.exports;
  },
});
`

const target = join(root, 'lib', CHUNK)
await writeFile(target, output, 'utf8')
console.log(`wrote lib/${CHUNK} (${(Buffer.byteLength(output) / 1024).toFixed(0)} KiB)`)
console.log(`  xterm   ${(Buffer.byteLength(xterm) / 1024).toFixed(0)} KiB`)
console.log(`  fit     ${(Buffer.byteLength(fit) / 1024).toFixed(0)} KiB`)
console.log(`  css     ${(Buffer.byteLength(css) / 1024).toFixed(0)} KiB`)
console.log(`  view    ${(Buffer.byteLength(fragment) / 1024).toFixed(1)} KiB`)
